// Writes stringify_cases_test.go: strings and what js-stringify 1.0.2 makes of them,
// on Node 24 (node record_stringify.mjs | gofmt > ../stringify_cases_test.go).
import { createRequire } from 'node:module'
import { goStr } from './golit.mjs'

const stringify = createRequire(import.meta.url)('/opt/original/node_modules/js-stringify/index.js')
const u = (...units) => String.fromCharCode(...units)
const inputs = [
  '', 'plain text', 'quotes " and \' and \\', '<script>alert("x")</script>', 'a/b', 'tab\tnew\nline\rcr',
  u(8, 12, 0, 1, 31, 127), u(0x2028, 0x2029), '日本 😀 é', u(0xd800), u(0xdc00, 0x41), u(0xd83d, 0xde00, 0xd83d),
  u(0xfeff, 0xa0, 0x85),
]
let out = `// Code generated by testdata/record_stringify.mjs from js-stringify 1.0.2 on Node 24; DO NOT EDIT.

package parser

var stringifyCases = []struct{ in, want string }{
`
for (const s of inputs) out += `\t{${goStr(s)}, ${goStr(stringify(s))}},\n`
process.stdout.write(out + '}\n')
